def fill_batches(apps, schema_editor):
    """Work out what is left of each past delivery and mark past deliveries as paid.

    Older stock is assumed to have sold first, so a product's current stock is
    given to its newest batches. Anything beyond the batches is stock from
    before batches were tracked.
    """
    from decimal import Decimal
    Product = apps.get_model('base', 'Product')
    PurchaseItem = apps.get_model('base', 'PurchaseItem')
    Purchase = apps.get_model('base', 'Purchase')
    for product in Product.objects.all():
        left = product.countInStock or Decimal('0')
        for item in PurchaseItem.objects.filter(product=product).order_by('-purchase__createdAt', '-id'):
            take = min(item.qty, max(left, Decimal('0')))
            item.remaining = take
            item.save(update_fields=['remaining'])
            left -= take
    for purchase in Purchase.objects.all():
        purchase.amount_paid = purchase.total_cost
        purchase.received_on = purchase.createdAt.date()
        purchase.save(update_fields=['amount_paid', 'received_on'])


